144	func (k *KubectlCmd) newGVKParser(oapiGetter discovery.OpenAPISchemaInterface) (*managedfields.GvkParser, error) {
145		doc, err := oapiGetter.OpenAPISchema()
146		if err != nil {
147			return nil, fmt.Errorf("error getting openapi schema: %w", err)
148		}
149		models, err := proto.NewOpenAPIData(doc)
150		if err != nil {
151			return nil, fmt.Errorf("error getting openapi data: %w", err)
152		}
153		var taintedGVKs []schema.GroupVersionKind
154		models, taintedGVKs = newUniqueModels(models)
155		if len(taintedGVKs) > 0 {
156			k.Log.Info("Duplicate GVKs detected in OpenAPI schema. This could cause inaccurate diffs.", "gvks", taintedGVKs)
157		}
158		gvkParser, err := managedfields.NewGVKParser(models, false)
159		if err != nil {
160			return nil, fmt.Errorf("failed to create GVK parser: %w", err)
161		}
